//go:build cgo

package sqlast

import (
	"reflect"
	"testing"
)

func inspectOne(t *testing.T, sql string) DDLStatement {
	t.Helper()
	got, err := InspectDDL(sql)
	if err != nil || len(got) != 1 {
		t.Fatalf("InspectDDL(%q) = %+v, %v; want one entry", sql, got, err)
	}
	return got[0]
}

func TestInspectDDLTableForms(t *testing.T) {
	got := inspectOne(t, "CREATE UNLOGGED TABLE rv.child "+
		"(a int GENERATED ALWAYS AS (b * 2) STORED,"+
		" b int GENERATED BY DEFAULT AS IDENTITY, c int CHECK (c > b) UNIQUE,"+
		" EXCLUDE USING gist (a WITH =)) INHERITS (rv.parent)")
	table := got.Table
	if table == nil || !table.Unlogged || table.Temporary ||
		!reflect.DeepEqual(table.Inherits, []QualifiedName{{Schema: "rv", Name: "parent"}}) ||
		table.PartitionOf != nil {
		t.Fatalf("table = %+v", table)
	}
	a, b, c := table.Columns[0], table.Columns[1], table.Columns[2]
	if a.Generated != GeneratedStored || !a.HasDefault || !a.DefaultVolatile || a.NotNull {
		t.Errorf("stored generated column = %+v", a)
	}
	if b.Generated != GeneratedIdentityByDefault || !b.NotNull || !b.HasDefault {
		t.Errorf("identity column = %+v", b)
	}
	wantC := []ConstraintDef{
		{Kind: ConstraintCheck, Columns: []string{"b", "c"}, Expr: "c > b"},
		{Kind: ConstraintUnique, Columns: []string{"c"}},
	}
	if !reflect.DeepEqual(c.Constraints, wantC) {
		t.Errorf("column c constraints = %+v, want %+v", c.Constraints, wantC)
	}
	last := table.Constraints[len(table.Constraints)-1]
	if last.Kind != ConstraintExclusion || !reflect.DeepEqual(last.Columns, []string{"a"}) {
		t.Errorf("exclusion constraint = %+v", last)
	}
	temp := inspectOne(t, "CREATE TEMP TABLE scratch (x text[], y numeric)")
	if !temp.Table.Temporary || temp.Table.Columns[0].Type != "text[]" ||
		temp.Table.Columns[1].Type != "numeric" {
		t.Errorf("temp table = %+v", temp.Table)
	}
	hash := inspectOne(t, "CREATE TABLE p (a int) PARTITION BY HASH (a)")
	if hash.Table.PartitionBy != "hash" {
		t.Errorf("partition_by = %q, want hash", hash.Table.PartitionBy)
	}
}

func TestInspectDDLRelationKinds(t *testing.T) {
	cases := []struct {
		sql        string
		kind       DDLKind
		objectType string
	}{
		{"DROP MATERIALIZED VIEW rv.mv", DDLDropTable, "materialized_view"},
		{"DROP FOREIGN TABLE rv.ft", DDLDropTable, "foreign_table"},
		{"ALTER VIEW rv.v RENAME TO w", DDLRenameTable, "view"},
		{"ALTER MATERIALIZED VIEW rv.mv RENAME TO mw", DDLRenameTable, "materialized_view"},
	}
	for _, c := range cases {
		got := inspectOne(t, c.sql)
		if got.Kind != c.kind || got.ObjectType != c.objectType ||
			got.Relation.Schema != "rv" {
			t.Errorf("%q = %s/%s/%v, want %s/%s", c.sql, got.Kind, got.ObjectType,
				got.Relation, c.kind, c.objectType)
		}
	}
	alter := inspectOne(t, "ALTER TABLE IF EXISTS rv.orders DROP COLUMN x")
	if !alter.IfExists || alter.Kind != DDLDropColumn {
		t.Errorf("ALTER TABLE IF EXISTS = %+v", alter)
	}
	view := inspectOne(t, "ALTER VIEW rv.v ALTER COLUMN a SET DEFAULT 1")
	if view.Kind != DDLOther || view.Command != "AlterTableStmt" {
		t.Errorf("ALTER VIEW = %+v, want other", view)
	}
	rc := inspectOne(t, "ALTER TABLE IF EXISTS rv.t RENAME COLUMN a TO b")
	if rc.Kind != DDLRenameColumn || !rc.IfExists || rc.NewName != "b" {
		t.Errorf("rename column = %+v", rc)
	}
}

func TestInspectDDLDefaultsAndSettings(t *testing.T) {
	cases := []struct {
		sql      string
		volatile bool
	}{
		{"ALTER TABLE t ADD COLUMN a timestamptz DEFAULT clock_timestamp()", true},
		{"ALTER TABLE t ADD COLUMN a int DEFAULT app.next_code()", true},
		{"ALTER TABLE t ADD COLUMN a text DEFAULT pg_catalog.lower('X')", false},
		{"ALTER TABLE t ADD COLUMN a jsonb DEFAULT '{}'::jsonb", false},
		{"ALTER TABLE t ADD COLUMN a date DEFAULT CURRENT_DATE", false},
		{"ALTER TABLE t ADD COLUMN a bigserial", true},
		{"ALTER TABLE t ALTER COLUMN a SET DEFAULT random()", true},
	}
	for _, c := range cases {
		got := inspectOne(t, c.sql)
		if got.Column == nil || got.Column.DefaultVolatile != c.volatile || !got.Column.HasDefault {
			t.Errorf("%q column = %+v, want volatile=%v", c.sql, got.Column, c.volatile)
		}
	}
	set := inspectOne(t, "SET search_path = app, public")
	if !reflect.DeepEqual(set.Setting, &Setting{Name: "search_path", Value: "app, public"}) {
		t.Errorf("setting = %+v", set.Setting)
	}
	all := inspectOne(t, "RESET ALL")
	if !reflect.DeepEqual(all.Setting, &Setting{Reset: true}) {
		t.Errorf("RESET ALL setting = %+v", all.Setting)
	}
	on := inspectOne(t, "SET enable_seqscan = off")
	if on.Setting.Value != "off" {
		t.Errorf("SET enable_seqscan value = %q", on.Setting.Value)
	}
}

func TestInspectDDLPreparedTransactionEndsBlock(t *testing.T) {
	got, err := InspectDDL("BEGIN; SET LOCAL lock_timeout = '1s'; PREPARE TRANSACTION 'x';" +
		" SELECT 1; COMMIT PREPARED 'x'")
	if err != nil {
		t.Fatalf("InspectDDL error = %v", err)
	}
	if got[3].InTransactionBlock || got[3].LockTimeoutMs != nil ||
		got[2].Transaction != "prepare" || got[4].Transaction != "commit_prepared" {
		t.Errorf("after PREPARE TRANSACTION: %+v", got[3])
	}
}

func TestInspectDDLTimeoutPointersAreNotShared(t *testing.T) {
	got, err := InspectDDL("SET lock_timeout = '1s'; SELECT 1; SELECT 2")
	if err != nil {
		t.Fatalf("InspectDDL error = %v", err)
	}
	*got[1].LockTimeoutMs = 99
	if *got[2].LockTimeoutMs != 1000 {
		t.Errorf("statements share one timeout value: %d", *got[2].LockTimeoutMs)
	}
}
